sys_script_client.script:
function showPriorityHint() {
    var impact = parseInt(g_form.getValue("impact")) || 2;
    var urgency = parseInt(g_form.getValue("urgency")) || 2;
    var p = impact + urgency - 1;
    if (p < 1) p = 1; if (p > 5) p = 5;
    var lbl = {1:"Critical",2:"High",3:"Moderate",4:"Low",5:"Planning"};
    g_form.clearMessages();
    g_form.addInfoMessage("Auto-Priority: Impact("+impact+") + Urgency("+urgency+") - 1 = " + p + " - " + lbl[p]);
}
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue === "") return;
    showPriorityHint();
}
